using System;
using Unity.Collections;

namespace UnityEngine.Rendering.HighDefinition
{
    internal static class HDShadowLightIndexResolver
    {
        private const int AMBIGUOUS_LIGHT_INDEX = -1;

        internal static void BuildMap(NativeArray<int> visibleLightEntityIndices, int visibleLightCount, ref NativeHashMap<int, int> map)
        {
            map.Clear();
            if (map.Capacity < visibleLightCount)
            {
                map.Capacity = visibleLightCount;
            }
            for (int index = 0; index < visibleLightCount; index++)
            {
                int dataIndex = visibleLightEntityIndices[index];
                if (dataIndex >= 0 && !map.TryAdd(dataIndex, index))
                {
                    map[dataIndex] = AMBIGUOUS_LIGHT_INDEX;
                }
            }
        }

        internal static int Resolve(int dataIndex, int requestLightIndex, int mappedLightIndex, NativeArray<int> visibleLightEntityIndices, int visibleLightCount)
        {
            if (mappedLightIndex >= 0)
            {
                return mappedLightIndex;
            }
            if (mappedLightIndex != AMBIGUOUS_LIGHT_INDEX || requestLightIndex < 0 || requestLightIndex >= visibleLightCount || requestLightIndex >= visibleLightEntityIndices.Length || visibleLightEntityIndices[requestLightIndex] != dataIndex)
            {
                throw new InvalidOperationException("Ambiguous shadow light mapping has no matching original native light index. Entity data index: " + dataIndex + "; request light index: " + requestLightIndex + ".");
            }
            return requestLightIndex;
        }
    }

}
